import { prismaAdapter } from "better-auth/adapters/prisma";
import { createAuthMiddleware } from "better-auth/api";
import { bearer, deviceAuthorization } from "better-auth/plugins";
import { tanstackStartCookies } from "better-auth/tanstack-start";

const isProduction = process.env.NODE_ENV === "production";

const apiUrl = process.env.API_URL ?? "http://localhost:3001";
const appUrl =
	process.env.BASE_URL ?? process.env.APP_URL ?? "http://localhost:3000";

const cookieSecure = apiUrl.startsWith("https://") || isProduction;
const cookieSameSite: "lax" | "none" = cookieSecure ? "none" : "lax";

const authConfig = {
	/**
	 * Database adapter.
	 *   Prisma:
	 *     import { prismaAdapter } from "better-auth/adapters/prisma";
	 *     import { prisma } from "@repomind/db";
	 *     database: prismaAdapter(prisma, { provider: "postgresql" }),
	 *

	 */
	database: prismaAdapter(prisma, { provider: "postgresql" }),

	hooks: {
		after: createAuthMiddleware(async (ctx) => {
			if (ctx.path.startsWith("/callback")) {
				try {
					const session = ctx.context.newSession;

					console.log("Session in after hook:", session);
					if (!session) {
						return;
					}

					console.log("Session after auth callback:", session);

					const user = await prisma.user.findUnique({
						where: {
							id: session.user.id,
						},
						select: {
							installationId: true,
						},
					});

					console.log("User installation ID:", user?.installationId);

					if (user?.installationId) {
						return;
					}

					// Get the Github Oauth access token for the account

					const account = await prisma.account.findFirst({
						where: {
							userId: session.user.id,
							providerId: "github",
						},
						select: {
							accessToken: true,
							accountId: true,
						},
					});

					console.log("GitHub account info:", account);

					if (!account?.accessToken) {
						return;
					}

					if (account.accountId) {
						await prisma.user
							.update({
								where: {
									id: session.user.id,
								},
								data: {
									githubId: BigInt(account.accountId),
								},
							})
							.catch(() => null);
					}

					console.log("gotten account from database");

					await linkInstallationFromGitHub(
						session.user.id,
						account.accessToken
					);

					console.log("Completed after hook");
				} catch (error) {
					if (process.env.NODE_ENV === "development") {
						console.error(
							`[auth] installation link failure ${safeErrorMessage(error)}`
						);
					}
				}
			}
		}),
	},

	// ── Session ─────────────────────────────────────────────────
	session: {
		expiresIn: 60 * 60 * 24 * 30, // 30 days
		updateAge: 60 * 60 * 24, // Refresh if > 1 day old
		cookieCache: {
			enabled: true,
			maxAge: 60 * 5, // Cache for 5 minutes
		},
	},

	// ── GitHub OAuth ────────────────────────────────────────────
	socialProviders: {
		github: {
			clientId: process.env.GITHUB_CLIENT_ID ?? "",
			clientSecret: process.env.GITHUB_CLIENT_SECRET ?? "",
			scope: ["read:user", "user:email"],
		},
	},
	advanced: {
		defaultCookieAttributes: {
			sameSite: cookieSameSite,
			secure: cookieSecure,
		},
		// Enable only if you intentionally share auth cookies across subdomains.
		crossSubDomainCookies: {
			enabled: process.env.AUTH_CROSS_SUBDOMAIN_COOKIES === "true",
		},
	},

	// ── Security ────────────────────────────────────────────────
	secret: process.env.BETTER_AUTH_SECRET ?? "dev-secret-change-in-prod",

	baseURL: apiUrl,

	trustedOrigins: [
		appUrl,
		process.env.APP_URL ?? "http://localhost:3000",
		"http://localhost:3000",
		"http://localhost:3001",
	],

	// ── Custom user fields ──────────────────────────────────────
	user: {
		additionalFields: {
			githubLogin: {
				type: "string",
				fieldName: "github_login",
				required: false,
				returned: true,
				input: false,
			},
			githubId: {
				type: "number",
				fieldName: "github_id",
				required: false,
				returned: true,
				input: false,
			},

			installationId: {
				type: "string",
				fieldName: "installation_id",
				required: false,
				returned: true,
				input: false,
			},
			apiKey: {
				type: "string",
				fieldName: "api_key",
				input: false,
				required: false,
				returned: false, // Never expose in session responses
			},
		},
	},

	// Plugins (uncomment to enable):
	plugins: [
		//   twoFactor(),         // import { twoFactor } from "better-auth/plugins";
		//   organization(),      // import { organization } from "better-auth/plugins";
		//   admin(),             // import { admin } from "better-auth/plugins";
		//   passkey(),           // import { passkey } from "better-auth/plugins";
		tanstackStartCookies(),
		/**
		 * Bearer plugin — lets the CLI use the access_token returned from
		 * the device flow as a Bearer token in Authorization headers.
		 * Without this, Better Auth only accepts session cookies.
		 */
		bearer(),

		/**
		 * Device Authorization Grant (RFC 8628).
		 *
		 * Flow for the CLI:
		 *   1. CLI calls POST /api/auth/device/code → gets { user_code, verification_uri, device_code }
		 *   2. CLI prints "Open https://repomind.dev/device and enter: ABCD-1234"
		 *   3. User opens browser, signs in with GitHub, enters user_code, clicks Approve
		 *   4. CLI polls POST /api/auth/device/token until it gets { access_token }
		 *   5. CLI stores access_token and uses it as Bearer token on every API call
		 *
		 * verificationUri: the page in the web app where users enter the code.
		 * We build this page in apps/web/src/routes/device.tsx
		 */
		deviceAuthorization({
			verificationUri: `${process.env.BASE_URL ?? "http://localhost:3000"}/device`,
			expiresIn: "15m", // CLI code expires after 15 minutes
			interval: "5s", // poll every 5 seconds minimum
			// Only allow our own CLI client ID — reject anything else
			validateClient: (clientId) => {
				return clientId === "repomind-cli";
			},
		}),
	],
	basePath: "/auth",
} satisfies BetterAuthOptions;

export const auth = betterAuth(authConfig);

/**
 * Use the user's GitHub OAuth token to find their GitHub App installations
 * and link the first matching one to their user row.
 *
 * This covers the case where a user installs the GitHub App BEFORE signing
 * in to the dashboard (the common path from the GitHub Marketplace).
 */

const getOctokit = ({ token }: { token: string }): Octokit => {
	return new Octokit({
		auth: token,
	});
};
async function linkInstallationFromGitHub(
	userId: string,
	accessToken: string
): Promise<void> {
	const octokit = getOctokit({ token: accessToken });
	const res = await octokit.rest.apps.listInstallationsForAuthenticatedUser();

	if (!res) {
		console.warn(`[auth] GitHub installations API returned ${res.status},`);
		return;
	}
	console.warn(`[auth] GitHub installations API returned ${res.status},`);

	for (const inst of res.data.installations) {
		const dbInstallation = await prisma.installation.findUnique({
			where: { githubInstallationId: BigInt(inst.id) },
			select: {
				id: true,
				users: {
					select: { id: true },
				},
			},
		});

		if (dbInstallation) {
			const githubLogin =
				"login" in inst.account ? inst.account.login : undefined;
			const githubEmail =
				"email" in inst.account ? inst.account.email : undefined;

			await prisma.user.update({
				where: { id: userId },
				data: { installationId: dbInstallation.id, githubLogin, githubEmail },
			});
			console.log(
				`[auth] linked user ${userId} → installation ${dbInstallation.id}`
			);
			return; // link to first matching installation and stop
		}
	}

	// No matching installation found yet — user may install the app later.
	// The dashboard will prompt them and call installations.link manually.
	console.log(
		`[auth] no matching installation found for user ${userId} — will prompt in dashboard`
	);
}

