import { checkout, polar, webhooks } from "@polar-sh/better-auth";
import { render } from "@react-email/components";
import { drizzleAdapter } from "better-auth/adapters/drizzle";
import { betterAuth } from "better-auth/minimal";
import { VerificationEmail } from "@/components/emails/templates/verification-email";
import type { EmailLocale } from "@/i18n/email";
import { db } from "@/lib/db";
import * as schema from "@/lib/db/schema";
import { serverEnv } from "@/lib/env/server";
import { polarClient } from "@/lib/polar";
import { onOrderPaid } from "@/lib/polar/events";
import { checkoutProducts } from "@/lib/polar/products";
import { resend } from "@/lib/resend";

export const auth = betterAuth({
  database: drizzleAdapter(db, {
    provider: "pg",
    schema: schema,
  }),
  experimental: {
    joins: true,
  },
  user: {
    additionalFields: {
      isPremium: {
        type: "boolean",
        input: false,
      },
      premiumGrantedAt: {
        type: "date",
        input: false,
      },
      preferredLocale: {
        type: "string",
        input: false,
      },
    },
  },
  session: {
    cookieCache: {
      enabled: true,
      maxAge: 60 * 2, // 2 minutes
      strategy: "compact",
      refreshCache: true,
    },
  },
  databaseHooks: {
    user: {
      create: {
        before: async (user, ctx) => {
          const acceptLanguage =
            ctx?.request?.headers?.get("accept-language") ?? "";
          const primaryLang = acceptLanguage
            .split(",")[0]
            ?.split("-")[0]
            ?.toLowerCase();

          const locale = primaryLang === "fr" ? "fr" : "en";

          return {
            data: {
              ...user,
              preferredLocale: locale,
            },
          };
        },
      },
    },
  },
  emailVerification: {
    autoSignInAfterVerification: true,
    sendOnSignUp: true,
    sendVerificationEmail: async ({ user, url }) => {
      const fullUser = user as typeof user & { preferredLocale?: string };

      void resend.emails.send({
        to: user.email,
        from: "noreply@notifications.otomai.app",
        subject: "Verify your email",
        html: await render(
          VerificationEmail({
            userName: fullUser.name,
            verificationUrl: url,
            locale: (fullUser.preferredLocale ?? "fr") as EmailLocale,
          }),
        ),
      });
    },
  },
  socialProviders: {
    discord: {
      clientId: serverEnv.DISCORD_CLIENT_ID,
      clientSecret: serverEnv.DISCORD_CLIENT_SECRET,
    },
  },
  plugins: [
    polar({
      client: polarClient,
      createCustomerOnSignUp: true,
      use: [
        checkout({
          products: checkoutProducts,
          successUrl: `${serverEnv.NEXT_PUBLIC_APP_URL}/success?checkout_id={CHECKOUT_ID}`,
          authenticatedUsersOnly: true,
        }),
        webhooks({
