import 'server-only'

import { betterAuth } from 'better-auth'
import { prismaAdapter } from 'better-auth/adapters/prisma'
import { createAuthMiddleware, twoFactor } from 'better-auth/plugins'

import { prisma } from '@/lib/prisma'

/**
 * Builds dynamic Better Auth configuration.
 * This function can be called on-demand to get the latest configuration.
 * @returns Promise resolving to Better Auth instance with current provider configurations.
 */
export async function buildBetterAuth() {
  /**
   * Get domain configuration for cookies based on environment.
   * @returns Domain setting for cookies or undefined to use default behavior.
   */
  const getDomainForCookies = () => {
    try {
      if (!process.env.BASE_URL) return undefined

      const url = new URL(process.env.BASE_URL)
      const hostname = url.hostname

      // For localhost or IP addresses, don't set a domain (use browser default)
      if (hostname === 'localhost' || RegExp(/^\d+\.\d+\.\d+\.\d+$/).exec(hostname)) {
        return undefined
      }

      // For production domains, prepend with '.' to include subdomains
      return process.env.NODE_ENV === 'production' ? `.${hostname}` : undefined
    } catch {
      return undefined
    }
  }

  try {
    // Get cookie domain setting
    const domain = getDomainForCookies()

    // Important: When running a production build locally on HTTP, make sure secure cookies are not enabled
    const isLocalEnvironment =
      process.env.BASE_URL?.includes('localhost') || process.env.BASE_URL?.includes('127.0.0.1')

    // Only use secure cookies when:
    //   1. in production AND not on localhost, OR
    //   2. explicitly using HTTPS
    const useSecureCookies =
      (process.env.NODE_ENV === 'production' && !isLocalEnvironment) ||
      process.env.BASE_URL?.startsWith('https://') ||
      false

    return betterAuth({
      database: prismaAdapter(prisma, {
        provider: 'mysql',
      }),

      baseURL: process.env.BASE_URL || process.env.BETTER_AUTH_URL || process.env.NEXT_AUTH_URL,
      secret: process.env.BETTER_AUTH_SECRET || process.env.NEXTAUTH_SECRET,

      user: {
        additionalFields: {
          emailVerified: {
            type: 'boolean',
            required: false,
            defaultValue: true,
          },
        },
      },

      emailAndPassword: {
        enabled: true,
        minPasswordLength: 12,
        maxPasswordLength: 128,
        requireEmailVerification: false,
      },

      plugins: [
        twoFactor({
          issuer: process.env.BASE_URL
            ? new URL(process.env.BASE_URL).hostname
            : process.env.APP_TITLE,
          backupCodes: {
            amount: 10,
            length: 10,
          },
        }),
      ],

      session: {
        expiresIn: 259200, // 3 days
        updateAge: 3600, // 1 hour
        cookieCache: {
          enabled: false, // Disabled due to large profile images in Better Auth's internal session data
        },
      },

      advanced: {
        cookiePrefix: 'next-auth', // Keep same cookie prefix for compatibility with NextAuth
        useSecureCookies,
        crossSubDomainCookies: {
          enabled: !!domain,
          domain,
        },
        // Disable state validation errors in development
        disableCSRFCheck: process.env.NODE_ENV === 'development',
      },

      hooks: {
        after: createAuthMiddleware(async (ctx) => {
          // Only run on callback completion, not every get-session call
          if (!ctx.path?.includes('/callback/')) {
            return
          }

          try {
            // Get session from context
            const session = ctx.context.newSession || ctx.context.session
            if (!session || !session.user || !session.user.id) {
              return
            }

            // Query database to get user and account data
            const user = await prisma.user.findUnique({
              where: { id: session.user.id },
              include: {
                accounts: true,
              },
            })

            if (!user || !user.accounts || user.accounts.length === 0) {
              return
            }

            // Get the most recently created account (the one just used for sign-in)
            const account = user.accounts.toSorted(
              (a, b) => b.createdAt.getTime() - a.createdAt.getTime(),
            )[0]

            if (!account) {
              return
            }

            // Update last logged in flag for all successful logins
            try {
              await prisma.userData.upsert({
                create: {
                  userId: user.id,
                  key: 'last_logged_in',
                  value: new Date().toUTCString(),
                },
                update: {
                  value: new Date().toUTCString(),
                },
                where: {
                  userId_key: {
                    userId: user.id,
                    key: 'last_logged_in',
                  },
                },
              })
            } catch {
              // Non-fatal error - continue processing
            }
          } catch {
            // Do nothing here
          }
        }),
      },
    })
  } catch (err) {
    console.error(`Error building Better Auth config: ${err}`)
    throw err
  }
}


