```typescript
async getSession(sessionToken: string) {
    try {
        const headers = new Headers()
        headers.append('cookie', `better-auth.session-token=${sessionToken}`)

        console.log({ headers })

        const result = await auth.api.getSession({
            headers
        });

        if (!result) {
            return {
                success: false,
                message: 'Session not found',
            };
        }

        return {
            success: true,
            message: 'Session retrieved successfully',
            user: {
                id: result.user.id,
                email: result.user.email,
                name: result.user.name,
            },
        };
    } catch (error) {
        return {
            success: false,
            message: error instanceof Error ? error.message : 'An unexpected error occurred',
        };
    }
}
```

### Controller Implementation (`src/controllers/auth.controller.ts`)

```typescript
getMe = async (
    request: FastifyRequest,
    reply: FastifyReply
) => {
    try {
        const sessionToken = request.headers.authorization?.replace('Bearer ', '') ||
            request.cookies['better-auth.session-token'];

        if (!sessionToken) {
            return reply.status(401).send({
                success: false,
                message: 'No session token provided',
            });
        }

        const result = await this.authService.getSession(sessionToken);
        return result;

    } catch (error) {
        return reply.status(500).send({
            success: false,
            message: 'Internal server error',
        });
    }
};
