			enabled: true,
			maxAge: 60 * 60 * 24 * 7
		}
	},

	callbacks: {
		session: async ({ session, user }: { session: Session; user: BetterAuthUser }) => {
			if (session && user) {
				const appUser = user as unknown as AppUser;
				return { ...session, user: appUser };
			}
			return session;
		}
	}
