```ts
import { fail, redirect, isRedirect } from '@sveltejs/kit';
import { z } from 'zod';
import { auth } from '$lib/server/auth';
import type { Actions } from './$types';
import { authClient } from '$lib/client/auth-client';

const LoginSchema = z.object({
	email: z.email({ message: 'Please enter a valid email address.' }),
	password: z.string().min(1, 'Password is required.')
});

export const actions: Actions = {
	email: async ({ request, fetch }) => {
		const formData = await request.formData();
		const body = Object.fromEntries(formData);
		const result = LoginSchema.safeParse(body);

		if (!result.success) {
			return fail(400, { data: body, errors: result.error.flatten().fieldErrors });
		}

		const { email, password } = result.data;

		try {
			const response = await fetch('/auth/sign-in/email', {
				method: 'POST',
				headers: { 'Content-Type': 'application/json' },
				body: JSON.stringify({ email, password })
			});

			if (response.ok) {
				throw redirect(303, '/dashboard');
			} else {
				const errorData = await response.json().catch(() => ({}));
				console.error('Login failed:', errorData);

				if (errorData.message === 'User not verified') {
					throw redirect(303, `/auth/check-email?email=${email}&unverified=true`);
				}

				return fail(401, {
					data: body,
					errors: { _general: ['Invalid email or password. Please try again.'] }
				});
			}
		} catch (err) {
			if (isRedirect(err)) {
				throw err;
			}
			console.error('Login Error:', err);
			return fail(500, { data: body, message: 'An internal server error occurred.' });
		}
	},

	google: async ({ request, url }) => {
		try {
			const response = await authClient.signIn.social({
				provider: 'google',
				callbackURL: '/',
				errorCallbackURL: '/',
				newUserCallbackURL: '/'
			});

			if (response.data && response.data.url) {
				throw redirect(303, response.data.url);
			}
		} catch (err) {
			if (isRedirect(err)) {
				throw err;
			}
			console.error('Google sign-in error:', err);
			return fail(500, { message: 'Could not sign in with Google.' });
		}
	}
};
