					session,
					memberProfile: null,
				};
			}

			const [result] = await db
				.select({ memberProfile })
				.from(member)
				.leftJoin(memberProfile, eq(member.memberProfileId, memberProfile.id))
				.where(
					and(eq(member.userId, user.id), eq(member.organizationId, session.activeOrganizationId))
