export interface InvitationEmailData {
	invitation: typeof schema.invitation.$inferSelect;
	organization?: { name: string } | null;
}

const buildInvitationUrl = (type: 'email' | 'phone', value: string) => {
	const baseUrl = resendEnv.CORS_ORIGIN ?? 'http://localhost:3000';
	return `${baseUrl}/sign-in?${new URLSearchParams({ type, value }).toString()}`;
};

export async function sendInvitationEmail(data: InvitationEmailData): Promise<void> {
	// TODO: Because Better auth is being weird here they do not have the context here to we cant get an actual http logger here
	const logger = getServerLogger();

	const invitation = data.invitation;
	const organizationName = data.organization?.name ?? 'an organization';

	// Phone invitation - just log for now (SMS integration TODO)
	if (invitation.invitationType === 'phone_number') {
		const phone = phoneFromTempEmail(invitation.email);
		if (!phone) {
			logger?.warn('Invalid phone invitation, skipping');
			return;
		}
		const invitationUrl = buildInvitationUrl('phone', phone);
		logger.info({ phone, invitationUrl }, '📱 Phone invitation URL');
		return;
	}

	// Email invitation
	const invitationUrl = buildInvitationUrl('email', invitation.email);
	if (process.env.NODE_ENV !== 'production' || !logger) {
		logger.info(
			{ email: invitation.email, organizationName, invitationUrl },
			'📧 Invitation Email'
		);
		return;
	}

	try {
		// Since better-auth doesn't provide transaction context, we use a standalone pattern
		// 1. Insert the outbound email record with status='queued'
		const outboundEmailId = await db.transaction(async (trx) => {
			return await prepareOrganizationInvitationEmail(trx, {
				organizationId: invitation.organizationId,
				memberProfileId: invitation.memberProfileId,
				invitationId: invitation.id,
				recipientEmail: invitation.email,
			});
		});

		// 2. Send the email and update the record
		await sendOrganizationInvitationEmail(db, outboundEmailId, {
			recipientEmail: invitation.email,
			senderName: organizationName,
			organizationName,
			invitationUrl,
			invitationId: invitation.id,
		});
	} catch (error) {
		logger.error({ error }, 'Failed to send invitation email');
	}
}
