	async function handleFetchSessionExpoStyle() {
		setIsFetchingSessionExpoStyle(true);
		setSessionResultExpoStyle(null);
		setError(null);

		try {
			const baseURL = env.EXPO_PUBLIC_SERVER_URL;
			const storagePrefix = 'acme';
			const cookieKey = `${storagePrefix}_cookie`;

			// Match expoClient plugin init hook logic exactly
			const storedCookie = SecureStore.getItem(cookieKey);
			const cookie = getCookie(storedCookie || '{}');
			const scheme =
				(Array.isArray(Constants.expoConfig?.scheme)
					? Constants.expoConfig?.scheme[0]
					: Constants.expoConfig?.scheme) ?? 'acme';
			const expoOrigin = `${scheme}://`;
			const url = `${baseURL}/api/auth/get-session`;

			sessionLog.debug('Expo-style fetch get-session - Request (matching expoClient plugin)', {
				url,
				cookieKey,
				hasStoredCookie: Boolean(storedCookie),
				storedCookieLength: storedCookie?.length ?? 0,
				storedCookiePreview: storedCookie?.slice(0, 120) ?? 'none',
				cookie: cookie || 'none',
				cookieLength: cookie?.length ?? 0,
				scheme,
				expoOrigin,
			});

			// Match expoClient plugin init hook exactly:
			// - headers: cookie (always included, even if empty), expo-origin, x-skip-oauth-proxy
			const res = await fetch(url, {
				method: 'GET',
				credentials: 'include',
				headers: {
					cookie, // Always include cookie header (matches plugin behavior)
					'expo-origin': expoOrigin,
					'x-skip-oauth-proxy': 'true',
				},
			});

			const body = await res.text();
			const setCookie = res.headers.get('set-cookie');
			const allHeaderKeys = [...res.headers.keys()];

			sessionLog.info('Expo-style fetch get-session - Response', {
				status: res.status,
				statusText: res.statusText,
				hasSetCookie: Boolean(setCookie),
				setCookieLength: setCookie?.length ?? 0,
				setCookiePreview: setCookie?.slice(0, 200) ?? 'none',
				allHeaders: allHeaderKeys.join(', '),
				bodyLength: body.length,
				bodyPreview: body.slice(0, 200),
			});

			let parsedBody;
			try {
				parsedBody = JSON.parse(body);
				sessionLog.debug('Expo-style fetch get-session - Parsed body', {
					userId: parsedBody?.user?.id,
					activeOrgId: parsedBody?.session?.activeOrganizationId,
					hasUser: Boolean(parsedBody?.user),
					hasSession: Boolean(parsedBody?.session),
				});
			} catch {
				parsedBody = null;
				sessionLog.warn('Expo-style fetch get-session - Failed to parse body as JSON', {
					bodyPreview: body.slice(0, 200),
				});
			}

			if (res.ok && parsedBody) {
				const userId = parsedBody.user?.id ?? t('Kein Benutzer');
				const activeOrgId = parsedBody.session?.activeOrganizationId ?? t('Keine Organisation');
				setSessionResultExpoStyle(
					t(
						'Session erfolgreich (Expo-Style): Status {{status}}, Benutzer {{userId}}, Organisation {{orgId}}',
						{
							status: res.status,
							userId,
							orgId: activeOrgId,
						}
					)
				);
			} else {
				setSessionResultExpoStyle(
					t('Fehler (Expo-Style): Status {{status}}, Body: {{body}}', {
						status: res.status,
						body: body.slice(0, 100),
					})
				);
			}
		} catch (err) {
			sessionLog.error('Expo-style fetch get-session - Error', {
				error: (err as Error).message,
				stack: (err as Error).stack,
			});
			setSessionResultExpoStyle(
				t('Fehler beim Expo-Style Abrufen der Session: {{message}}', {
					message: (err as Error).message,
				})
			);
		} finally {
			setIsFetchingSessionExpoStyle(false);
		}
	}
